import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { LogOut, BookOpen, LayoutDashboard, Menu, X } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

// Brand fonts (Horizon + Anonymous Pro), self-hosted and loaded once for the whole site
const BRAND_FONTS = `@font-face{font-family:'Horizon';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 950;font-style:normal;font-display:swap}@font-face{font-family:'Anonymous Pro';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 500;font-style:normal;font-display:swap}@font-face{font-family:'Anonymous Pro';src:url(data:font/woff2;base64,) format('woff2');font-weight:600 950;font-style:normal;font-display:swap}`;
const LOGO = 'data:image/png;base64,';

export const Navigation = () => {
  const { user, signOut, isAdmin } = useAuth();
  const location = useLocation();
  const isActive = (path: string) => location.pathname === path;
  const [menuOpen, setMenuOpen] = useState(false);
  const close = () => setMenuOpen(false);

  return (
    <>
      <style>{`
        .nav-root {
          position: fixed;
          top: 0; left: 0; right: 0;
          z-index: 50;
          background: #f5f4f1;
          border-bottom: 1px solid #dedbd6;
        }
        .nav-inner {
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 16px 40px;
        }
        .nav-login, .nav-link {
          font-family: 'Anonymous Pro', 'Courier New', monospace;
          font-size: 11px; font-weight: 400; letter-spacing: 0.09em;
          text-transform: uppercase; color: #67625c;
          text-decoration: none; transition: color 0.2s;
          display: flex; align-items: center; gap: 6px;
        }
        .nav-login { border-bottom: 1px solid #bbb5ac; padding-bottom: 3px; }
        .nav-login:hover, .nav-link:hover { color: #191a1e; }
        .nav-link.active { color: #191a1e; border-bottom: 1px solid #191a1e; padding-bottom: 2px; }
        .nav-logo { text-decoration: none; display: block; }
        .nav-logo-img { display: block; height: 44px; width: auto; }
        .nav-desktop {
          display: flex; align-items: center; gap: 22px;
          min-width: 120px; justify-content: flex-end;
        }
        .nav-signout {
          background: none; border: none; cursor: pointer;
          color: #67625c; transition: color 0.2s;
          display: flex; align-items: center; padding: 0;
        }
        .nav-signout:hover { color: #191a1e; }
        .nav-hamburger {
          display: none; background: none; border: none; color: #191a1e;
          cursor: pointer; padding: 4px; align-items: center;
        }
        .nav-mobile-menu { display: none; }
        .nav-mobile-panel {
          flex-direction: column; background: #f5f4f1;
          border-top: 1px solid #dedbd6;
        }
        .nav-mobile-link {
          font-family: 'Anonymous Pro', 'Courier New', monospace;
          font-size: 13px; font-weight: 400; letter-spacing: 0.09em;
          text-transform: uppercase; color: #191a1e;
          text-decoration: none; padding: 17px 20px;
          border: 0; border-bottom: 1px solid #dedbd6;
          display: flex; align-items: center; gap: 12px;
          background: none; width: 100%; text-align: left; cursor: pointer;
        }
        .nav-mobile-link:active { background: #eae7e1; }
        .nav-root a:focus-visible, .nav-root button:focus-visible { outline: 2px solid #191a1e; outline-offset: 3px; }

        @media (max-width: 640px) {
          .nav-inner { padding: 14px 16px; }
          .nav-logo-img { height: 34px; }
          .nav-desktop { display: none; }
          .nav-hamburger { display: flex; }
          .nav-mobile-menu { display: flex; }
        }
      `}</style>
      <style>{BRAND_FONTS}</style>

      <nav className="nav-root">
        <div className="nav-inner">

          <Link to="/" className="nav-logo" onClick={close}>
            <img className="nav-logo-img" src={LOGO} alt="Mariels Brow Academy" width={640} height={106} />
          </Link>

          <div className="nav-desktop">
            <a href="/tools.html" className="nav-link">Shop</a>
            {user ? (
              <>
                <Link to="/courses" className={`nav-link ${isActive('/courses') ? 'active' : ''}`}>Courses</Link>
                <Link to="/dashboard" className={`nav-link ${isActive('/dashboard') ? 'active' : ''}`}>
                  <BookOpen className="w-3 h-3" />Dashboard
                </Link>
                <Link to="/community" className={`nav-link ${isActive('/community') ? 'active' : ''}`}>Community</Link>
                {isAdmin && (
                  <Link to="/admin" className={`nav-link ${isActive('/admin') ? 'active' : ''}`}>
                    <LayoutDashboard className="w-3 h-3" />Admin
                  </Link>
                )}
                <button onClick={() => signOut()} className="nav-signout" title="Sign Out">
                  <LogOut className="w-4 h-4" />
                </button>
              </>
            ) : (
              <Link to="/login" className="nav-login">Sign Up / Login</Link>
            )}
          </div>

          <button className="nav-hamburger" aria-label="Menu" onClick={() => setMenuOpen((o) => !o)}>
            {menuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>

        </div>

        {menuOpen && (
          <div className="nav-mobile-menu nav-mobile-panel">
            <a href="/tools.html" className="nav-mobile-link" onClick={close}>Shop</a>
            {user ? (
              <>
                <Link to="/courses" className="nav-mobile-link" onClick={close}>Courses</Link>
                <Link to="/dashboard" className="nav-mobile-link" onClick={close}>
                  <BookOpen className="w-4 h-4" />Dashboard
                </Link>
                <Link to="/community" className="nav-mobile-link" onClick={close}>Community</Link>
                {isAdmin && (
                  <Link to="/admin" className="nav-mobile-link" onClick={close}>
                    <LayoutDashboard className="w-4 h-4" />Admin
                  </Link>
                )}
                <button onClick={() => { signOut(); close(); }} className="nav-mobile-link">
                  <LogOut className="w-4 h-4" />Sign Out
                </button>
              </>
            ) : (
              <Link to="/login" className="nav-mobile-link" onClick={close}>Sign Up / Login</Link>
            )}
          </div>
        )}
      </nav>
    </>
  );
};
